# Now I understand the pattern!
# In the demo: 4 is foreground, 8 is background
# Output: some 4→2 (filled interior), some 4→4 (outline/boundary)
# This is a flood fill: interior becomes 2, outline stays as original

# For our task: 1 is foreground on 8 background
# We need to:
# 1. Find all enclosed regions of 8s
# 2. Fill those regions with 2
# 3. Keep the foreground (1) as outline

# Let me implement flood fill to find enclosed regions
input_grid = [
    [8, 8, 1, 1, 1, 1, 1, 1, 8],
    [8, 8, 1, 8, 1, 8, 8, 8, 8],
    [8, 8, 8, 8, 1, 8, 8, 8, 8],
    [8, 8, 1, 8, 1, 8, 8, 1, 8],
    [8, 8, 1, 8, 1, 8, 8, 1, 8],
    [8, 8, 1, 8, 8, 8, 8, 1, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8],
    [8, 8, 8, 8, 8, 8, 8, 8, 8]
]

# Flood fill algorithm - find background pixels not connected to outer boundary
# Start from edges and mark all reachable 8s as "outside"
# Remaining 8s are "enclosed" and should become 2

def flood_fill_outside(grid, rows, cols):
    """Mark all 'outside' background pixels"""
    outside = set()

    # Start from all edge background pixels and spread
    for i in range(rows):
        if grid[i][0] == 8:
            expand(grid, i, 0, outside)
        if grid[i][cols-1] == 8:
            expand(grid, i, cols-1, outside)
    for j in range(cols):
        if grid[0][j] == 8:
            expand(grid, 0, j, outside)
        if grid[rows-1][j] == 8:
            expand(grid, rows-1, j, outside)

    return outside

def expand(grid, r, c, outside):
    """BFS from edge to mark reachable 8s"""
    rows, cols = len(grid), len(grid[0])
    visited = set()

    # Start from (r,c) only if at edge
    if r == 0 or r == rows-1 or c == 0 or c == cols-1:
        stack = [(r, c)]
        visited.add((r, c))

    while stack:
        cr, cc = stack.pop()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] == 8:
                    if nr == 0 or nr == rows-1 or nc == 0 or nc == cols-1:
                        visited.add((nr, nc))
                    stack.append((nr, nc))
                    visited.add((nr, nc))

# Correct flood fill - simpler approach
from collections import deque

def flood_fill_outside_correct(grid):
    rows, cols = len(grid), len(grid[0])
    outside = [[False]*cols for _ in range(rows)]

    # Queue for BFS
    queue = deque()

    # Add all edge 8s to queue
    for i in range(rows):
        if grid[i][0] == 8:
            queue.append((i, 0))
            outside[i][0] = True
        if grid[i][cols-1] == 8:
            queue.append((i, cols-1))
            outside[i][cols-1] = True
    for j in range(cols):
        if grid[0][j] == 8:
            queue.append((0, j))
            outside[0][j] = True
        if grid[rows-1][j] == 8:
            queue.append((rows-1, j))
            outside[rows-1][j] = True

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if grid[nr][nc] == 8 and not outside[nr][nc]:
                    queue.append((nr, nc))
                    outside[nr][nc] = True

    return outside

